	elseif kind == "fire" then
		local fire = Instance.new("Fire")
		fire.Heat, fire.Size = 9, 5
		fire.Color, fire.SecondaryColor = Color3.fromRGB(255, 150, 40), Color3.fromRGB(255, 70, 20)
